function tryParse(t){try{return JSON.parse(t)}catch{return"unparseable"}}print(JSON.stringify(tryParse('{"a":1}'))),print(tryParse("not json"));let result,attempts=0;function unreliable(){if(attempts++,attempts<3)throw new Error("fail#"+attempts);return"succeeded on attempt "+attempts}for(let t=0;t<5;t++)try{result=unreliable();break}catch{print("attempt",t,"failed, no binding needed")}print(result);